DOC=ROOT/'docs/frontend-v1.1.0'; SRC=ROOT/'assets-source/frontend-v1.1.0'; RUN=ROOT/'assets-runtime/frontend-v1.1.0'
for p in [DOC,SRC,RUN,DOC/'concepts']: p.mkdir(parents=True,exist_ok=True)
style='Original Pantheon Realms fantasy strategy game, a cohesive classic late-1990s illustrated strategy-game interface: aged warm parchment, restrained carved dark blue stone, thin antique-gold bevels, tactile engraved controls, jewel-colored faction accents, beautifully painted mythic artwork. Strong hierarchy, readable roomy text, compact purposeful ornament, no website navbar, no dashboard metric cards, no modern pill controls, no photorealism. Landscape 16:10 full screen, target 1600x1000. Entire image is one polished game screen, no device frame or explanatory annotations. '
specs=[
('01','title-hall','Main menu',['S01'],'MainMenu.tsx','A quiet mythic hall framing a glowing distant world at twilight. Balanced hints of all SIX cultures around the edges: Greek, Norse, Egyptian, Japanese, Celtic, Mesoamerican. Central title PANTHEON REALMS. Below title a narrow elegant vertical carved menu: Continue, New Game, Load Game, Encyclopedia, Settings, Quit. No technical build diagnostics. All controls readable; background calm behind the menu.','Keep Continue compatibility and storage checks; Quit remains desktop only. Existing menu background rotation can remain, or use the new hall. Read release version from package data; move detailed rules/content/storage information to Settings > Saves.'),
('02','new-game','Choose a journey',['S02'],'Setup.tsx','Title Choose your journey. Four large painted folio panels in a 2x2 arrangement with distinct illustrations: Campaign a heroic story scroll; Skirmish two opposing war banners; Random Map a magical uncharted atlas; Map Editor a quill and drafting tools over a terrain map. Exact four labels Campaign, Skirmish, Random Map, Map Editor. Short text below each. Back bottom left. Preserve generous image area.','Use the existing four routes. Do not add online play, accounts, downloads or unsupported modes. Mode cards are real buttons with descriptions and keyboard focus.'),
('03','campaign','Campaign chronicles',['S03A'],'Setup.tsx','Title Campaign Chronicles. Left page has six compact selectable illustrated campaign rows labeled Greek, Norse, Egyptian, Japanese, Celtic, Mesoamerican. Greek selected. Large right page painted Greek campaign cover, story paragraph and a decorative numbered mission sequence presented as a read-only story outline. Bottom difficulty choice Story / Normal / Hard and Begin Campaign button. Back button. Do not show selectable mission nodes, chapter replay, invented unlocks or invented completion badges.','Bind all covers, names, descriptions, missionIds and difficulty effects to catalog. Mission list previews sequence only. Begin calls existing startCampaign with first mission and existing default patron; no replay selection, progress locks, or new patron step.'),
('04','skirmish','Skirmish atlas',['S03B'],'Setup.tsx','Title Skirmish Atlas. Left folio page a 2x3 grid of painted terrain thumbnails with names beneath, one gold selection frame. Right page one larger evocative landscape painting, selected map title, concise objective text, icon-led facts Empires, Size, Victory, Climate. Lower right Continue button and bottom left Back. Painting is scenic illustration, not a precise map diagram. No technical IDs or raw JSON.','Preserve authored map and legacy scenario paths. Authored map details use existing Brief 14 painting, actual player count/cells/victory/biome/wealth/reveal facts. Legacy unavailable scenarios retain disabled explanations.'),
('05','random-map','Random map atlas',['S19'],'RandomSetup.tsx','Title Shape an Uncharted Realm. Three engraved chapter tabs Land / Empires / Rules. Land selected. Left two-thirds has EXACTLY NINE illustrated landscape tiles in 3x3 grid, labels Continental, Highlands, Lake Isle, Wild Forest, Marshlands, Crossroads, Archipelago, Twin Continents, Central Valley. Right parchment page selected Highlands illustration, short description, Size Small Medium Large Huge and Empires selector 2 3 4 5 6. Text Illustrative landscape. Footer Back and Create World. No seed number, no coordinate grid, no claim of live generated preview.','Preserve one RandomSetup state across proposed Land/Empires/Rules chapters. Use SKIRMISH_MAP_TYPES IDs and summaries. Cards illustrate archetypes, never the generated result. Twin Continents only two empires; four or more need large/huge. No seed field; existing Create generates fresh seed/retries/validation.'),
('06','empire-setup','Pantheons and empires',['S04','S23'],'MapSetup.tsx','Title Gather the Empires. Six faction banners across top labeled Greek Norse Egyptian Japanese Celtic Mesoamerican. Below parchment setup board four horizontal seat rows, each with banner, player name field, Human or AI control and a god portrait selector for human players. Right modest selected map painting, difficulty Easy Normal Hard only if AI exists. Bottom Back and Begin. Strong decorative board framing but calm aligned controls. No network lobby, chat, ready checks, usernames or online indicators.','For legacy scenario pantheon selection keep existing starting-patron behavior. For authored/random matches use actual seat count, human/AI controller, human names and valid gods. Require at least one human; preserve unowned-town and AI-difficulty conditions. Authored/random go directly to adventure.'),
('07','encyclopedia','Encyclopedia index',['S16-creatures','S16-gods','S16-heroes','S16-town','S16-spells','S16-skills','S16-artifacts','S16-abilities'],'Encyclopedia.tsx','Large illuminated book title Encyclopedia. TOP TWO ROWS of FOUR tabs with all EIGHT labels: Bestiary, Gods, Heroes, Towns, Spells, Skills, Artifacts, Abilities. Left narrow rail shows all SIX faction labels Greek, Norse, Egyptian, Japanese, Celtic, Mesoamerican PLUS Neutral. Main open parchment displays seven creature family rows with base and upgraded portrait pairs, readable names, small tier medallions. Search field top of content. Back bottom. Avoid arbitrary numeric statistics; this is an index rather than detail.','Preserve all eight categories and neutral creatures. Search/filter is a proposed local catalog presentation enhancement; reset/clamp selection on filtering. Render seven families per faction from data, both forms. Other categories use their actual data, not a forced seven-row creature layout.'),
('08','creature-detail','Animated bestiary detail',['S18'],'UnitDetail.tsx','Open book creature detail titled Griffin. Left parchment page large name, base/upgraded portrait selectors, clear icon-led attributes and ability/lore areas. Right page majestic stylized griffin standing in a restrained neutral stage with wide space around wings; viewer controls below labeled Idle, Move, Attack, Defend, Hit, Death, Victory. Play/pause, speed and facing buttons. Bottom Back. No fake video seek timeline, no locked states, no invented stats numbers. Match the existing book reference style.','Retain existing requiredAnimations per creature including optional shoot/fly/cast/ability only when supported, current facing/rate/restart/autoplay and loading/fallback states. Each base/upgraded form resolves its actual creatureId. Reduced motion uses still; no hidden essential information on hover.'),
('09','settings','Settings ledger',['S17-gameplay','S17-interface','S17-display','S17-audio','S17-accessibility','S17-controls','S17-storage'],'Settings.tsx','Title Settings. Left vertical carved chapter tabs with EXACTLY SEVEN labels Gameplay, Interface, Display, Audio, Accessibility, Controls, Saves. Audio selected. Main parchment contains five aligned gold-track sliders Master, Music, Ambience, Interface, Combat, numeric percentage fields to right. Lower checkboxes Mute all, Mute in background, Calmer sound, and Test Sound. Footer Restore defaults, Revert, Apply, Back. Visible unsaved changes small message. Quiet backdrop; highly legible; no ornate object over any control.','All settings stay bound to current draft. Apply persists; Revert restores; Back with edits confirms discard. Audio previews draft and restores committed prefs on exit. Keep actual graphics quality/adaptive resolution/FPS controls and platform window-mode restrictions. Seven chapters and all keyboard rebindings remain.'),
('10','save-archive','Saved journeys',['D03','D04'],'../dialogs/Overlays.tsx','Wide framed parchment modal titled Saved Journeys over dim quiet hall. Left scrollable slots, Manual saves / Autosaves / Checkpoint labels. Show one occupied sample row and some Empty slot rows. Right selected journey panel with small scenic mission illustration, save name, day/hero/faction metadata, Load primary button, secondary Export and Delete. Footer Import, Close. Save tab visibly unavailable from title screen. No cloud symbols, accounts or fake captured gameplay thumbnails.','Retain actual manual/autosave/checkpoint order; Save disabled without session. MissionThumb is an illustration, not a stored screenshot. Keep compatibility reason and disabled Load, reading/unavailable/empty states, import/export/delete, overwrite/load-discard confirmations and name maxLength 60.'),
('11','map-library','Local map library',['E03'],'MapEditor.tsx','Modal title Map Library on top of dimmed atlas editor. Parchment rows of locally authored maps with small terrain icons, name, size and empires. Selected row has a gold edge and right detail pane. Separate section Templates. Footer buttons Import, Open, Export, Delete, Close. Labels Local maps and Templates. No online marketplace or cloud. Room for helpful Empty library message with a small blank scroll case illustration.','Keep local map storage, import JSON parse/validation, copy templates into editable documents, export and delete confirmation. Never imply cloud, shared maps, workshop or automatic overwrite of catalog templates. Library is existing editor overlay.'),
('12','map-editor','Cartographer workspace',['S22-map','S22-empires','S22-site','S22-check','E01','E02','E04','E05'],'MapEditor.tsx','Full fantasy map editor screen. Large central fixed-angle stylized hex terrain canvas with forest, hills, lakes, towns and roads. Compact top engraved buttons New, Generate, Open, Save, Export, Play. Left toolbox Select, Erase, Terrain, Roads, Sites. Right parchment inspector tabs Map, Empires, Site, Check with modest map options. Bottom context hint and validation count. Ornamental border stays thin and outside canvas. Functional authoring tool, no website cards, no unrequested 3D rotation gizmo.','Preserve paint/select/erase/road/site tools, map/empires/site/check inspectors, validation issue navigation, new/generate/play dialogs, unsaved exit confirmation, JSON export and panning. Keep editor viewport unobstructed; no perspective rotation. All data validation remains authoritative.'),
('13','hall-of-records','Hall of records',['S21'],'Summary.tsx','Title Hall of Records. A handsome parchment ledger in carved dark stone frame. Two tabs Skirmish and Campaign. Table has columns Rank, Player, Pantheon, Map, Result, Days, Difficulty, Score, Date. Three restrained illustrative example rows, gold/bronze rank seals but no giant victory trophies. Footer Back and discreet Clear Records. Local records subtitle. No online leaderboard, account portraits or friend invitations.','Existing local HighScoresScreen route. Preserve loading/empty state, current columns and both tables. Clear records requires current confirmation and leaves saves intact. A small title-menu Records link is an OPTIONAL proposed navigation addition, not an existing action.'),
('14','shared-dialog','Confirmations and quiet feedback',['D11','D05'],'../dialogs/Overlays.tsx','One compact confirmation modal centered over softly dimmed settings ledger. Title Discard changes? Body Your changes have not been applied. Two clear rectangular gold-edged buttons Keep editing and Discard. Subtle warning wax-seal icon, warm parchment, restrained dark stone frame, no enormous red alert or technical traceback. Footer-free background settings remains recognizable but inaccessible under modal.','Shared confirmation, help, validation and error styling. Preserve original destructive callbacks, modal focus trapping/return focus/Escape policy and exact reasons. Keep editing is safe initial focus. Do not turn errors into decorative art or remove troubleshooting details; collapse optional technical detail only.')
]
jobs=[]; recipes=[]
for id,slug,title,ids,source,prompt,behavior in specs:
    filename=f'{id}-{slug}.png'
    jobs.append(dict(key='concept-'+slug,kind='concept',file=filename,destination=str(DOC/'concepts'/filename),transparent=False,prompt='Use case: ui-mockup. '+style+prompt,refs=['C:/Users/lazeb/Desktop/pantheon_realms/docs/gui-concepts-2026-10-10/12-bestiary-codex-v2.png']))
    recipes.append(dict(id=id,slug=slug,title=title,catalog=ids,concept='concepts/'+filename,source='packages/ui/src/screens/'+source,behavior=behavior))
artstyle='Use case: stylized-concept. Production artwork for Pantheon Realms, painted classic fantasy strategy game, rich readable stylized forms, antique gold and navy with warm parchment light, painterly rather than photorealistic. No lettering, numbers, logos, UI, buttons, labels, borders or watermark. Native clean illustration. '
assets=[
('backdrop.title-hall','backdrop-title-hall.png','Wide 16:10 atmospheric hall of six mythic traditions. Sparse peripheral reliefs evoke Greek laurel, Norse knotwork, Egyptian sun, Japanese cloud, Celtic oak and Mesoamerican stepped geometry with equal visual weight. Distant subtle gold horizon. Dark muted low-detail CENTER SIXTY PERCENT reserved for menu. No characters or foreground furniture across center. Render background only.',False),
('backdrop.atlas','backdrop-atlas.png','Wide 16:10 oblique cartographer desk, mostly quiet dark worn leather surface across central 75 percent. Dim peripheral rolled parchment at far left edge, small antique brass compass at far lower right corner and soft warm light along upper edge. Empty central surface is uninterrupted dark low contrast. No map lines behind future UI. Render background only.',False),
('backdrop.library','backdrop-library.png','Wide 16:10 dim mythic library alcove. Book shelves glimpsed only at far left and right edges, soft warm amber light, desaturated navy brown quiet center occupying 75 percent. No prominent central objects, no lettering on book spines. Empty atmospheric backdrop behind a large UI book.',False),
('mode.campaign','mode-campaign.png','Landscape 4:3 compact emblematic vignette: a rolled illustrated chronicle and a bronze heroic helmet beside a small mythic horizon, warm gold spotlight. Clearly about beginning a story. Large readable forms and little peripheral detail. No pages containing text.',False),
('mode.skirmish','mode-skirmish.png','Landscape 4:3 compact dramatic vignette: opposing blue and red war standards on spears overlooking a small open field, distant stylized armies represented by a handful of tiny banners. Large silhouettes, visual tactical confrontation. No gore or lettering.',False),
('mode.random-map','mode-random-map.png','Landscape 4:3 compact magical atlas vignette: small floating miniature terrain of hills, islands and forest forming above an open blank atlas, brass compass nearby, soft teal golden light. Concept of uncharted world generation. No dice numbers or text.',False),
('mode.map-editor','mode-map-editor.png','Landscape 4:3 compact cartographer vignette: antique quill and brass dividers over a tiny painted terrain plan with forest mountains road, a few terrain tokens at the margin. Large shapes, readable at small scale, no writing.',False),
('empty.archive','empty-archive.png','Single isolated small closed blank leather folio beside an empty scroll case, antique gold fittings, three large readable shapes, softly painted stylized fantasy prop, front three-quarter view. Genuinely transparent background, no shadow plane, no UI container, no lettering. Decorative empty-state illustration.',True)
]
types=re.findall(r"\{ id: '([^']+)', label: '([^']+)', summary: '([^']+)'",(ROOT/'packages/mapgen/src/skirmish.ts').read_text(encoding='utf8'))
for id,label,desc in types[:9]:
    extra=' Pure inland landscape without surrounding ocean or waterways.' if id=='continental' else ''
    assets.append(('random.'+id,'random-'+id+'.png','Landscape 4:3 terrain archetype thumbnail, high oblique view of a miniature continuous terrain diorama with edges outside frame. '+label+': '+desc+'. Make these terrain relationships visually clear with a few large forms. Broad readable forest masses, warm paths, stylized rock, calm teal water where applicable. Neutral faction geography, no armies, no lettering, no grid. Illustrative archetype rather than literal generated layout.'+extra,False))
for id,file,prompt,trans in assets:
    jobs.append(dict(key='frontend.'+id,kind='asset',file=file,destination=str(SRC/file),transparent=trans,prompt=artstyle+prompt,refs=[]))
(SRC/'generation-queue.json').write_text(json.dumps(jobs,indent=2),encoding='utf8')
(DOC/'screen-recipes.json').write_text(json.dumps(recipes,indent=2),encoding='utf8')
(DOC/'random-map-types.json').write_text(json.dumps([dict(id=i,label=l,summary=d,asset='frontend.random.'+i) for i,l,d in types[:9]],indent=2),encoding='utf8')
print(json.dumps({'jobs':len(jobs),'concepts':len(specs),'production':len(assets)}))
